('advanced-native-1408', '["phrase"]'::jsonb, '{"advanced-native-1408-v1-audio":{"type":"mc","answers":["原有興趣因項目而被激發。"],"options":["項目令他完全失去興趣。","他的興趣從一開始就已充分發展。","原有興趣因項目而被激發。","他原本從未接觸過歷史。"]},"advanced-native-1408-v2-reply":{"type":"mc","answers":["It gave him a reason to try drawing again.","He discovered a side of himself he had rarely used.","It made an old hobby feel exciting again.","It awakened an interest that had been half-asleep."],"options":["It gave him a reason to try drawing again.","He discovered a side of himself he had rarely used.","It made an old hobby feel exciting again.","It awakened an interest that had been half-asleep."]},"advanced-native-1408-v1-scene":{"type":"mc","answers":["Her creativity had been half-asleep."],"options":["She had permanently lost every creative ability.","Her creativity had been half-asleep.","Her creativity had been fully developed and constantly used."]},"advanced-native-1408-v1-contrast":{"type":"mc","answers":["它必定表示能力永遠消失，不能再發展。"],"options":["能力可能存在，但未充分運用。","新的經驗可能激發原有興趣。","它必定表示能力永遠消失，不能再發展。"]},"advanced-native-1408-v1-branch":{"type":"mc","answers":["Perhaps a small creative task could wake that interest up again."],"options":["Stick to familiar routines and leave creative experiments until the ability feels active by itself.","Put your effort into presenting old work rather than using that ability in a fresh task.","Perhaps a small creative task could wake that interest up again."]},"advanced-native-1408-v1-final":{"type":"open","answers":["Her interest in writing had been half-asleep until the class project inspired her.","A half-asleep interest in stories came alive when she joined the class project."],"options":[]}}'::jsonb),
